     4→import type { Frame } from '../types/frame';
     5→
     6→export function FrameListPage() {
     7→  const [frames, setFrames] = useState<Frame[]>([]);
     8→  const [loading, setLoading] = useState(true);
     9→  const [error, setError] = useState<string | null>(null);
    10→  const navigate = useNavigate();
    11→
    12→  useEffect(() => {
    13→    getFrames()
    14→      .then(setFrames)
    15→      .catch((err) => setError(err.message))
    16→      .finally(() => setLoading(false));
    17→  }, []);
    18→
    19→  function formatDate(dateString: string): string {
    20→    const date = new Date(dateString);
    21→    return date.toLocaleDateString('en-GB', {
    22→      day: '2-digit',
    23→      month: 'short',
    24→      year: 'numeric',
    25→    });
    26→  }
    27→
    28→  function getStatusChipClass(status: string): string {
    29→    switch (status.toUpperCase()) {
    30→      case 'LIVE':
    31→        return 'chip success';
    32→      case 'DRAFT':
    33→        return 'chip neutral';
    34→      case 'PENDING':
    35→        return 'chip warning';
    36→      case 'INACTIVE':
    37→        return 'chip error';
    38→      default:
    39→        return 'chip neutral';
