    64→        alignItems: 'center',
    65→        marginBottom: 'var(--sp-3)'
    66→      }}>
    67→        <div>
    68→          <h1 style={{ margin: 0, fontSize: '20px', fontWeight: 600 }}>
    69→            Frames
    70→          </h1>
    71→          <p style={{ margin: '4px 0 0', color: 'var(--text-secondary)', fontSize: '13px' }}>
    72→            {frames.length} {frames.length === 1 ? 'frame' : 'frames'}
    73→          </p>
    74→        </div>
    75→        <div style={{ display: 'flex', gap: 'var(--sp-1)' }}>
    76→          <Link to="/upload" className="btn secondary">
    77→            Upload CSV
    78→          </Link>
    79→          <Link to="/frames/new" className="btn primary">
    80→            New frame
    81→          </Link>
    82→        </div>
    83→      </header>
    84→
    85→      {frames.length === 0 ? (
    86→        <div className="surface" style={{ padding: 'var(--sp-4)', textAlign: 'center' }}>
    87→          <p style={{ color: 'var(--text-secondary)' }}>No frames yet.</p>
    88→          <p style={{ marginTop: 'var(--sp-2)' }}>
    89→            <Link to="/frames/new" className="btn primary">Create your first frame</Link>
    90→            {' or '}
    91→            <Link to="/upload" className="btn secondary">Upload a CSV</Link>
    92→          </p>
    93→        </div>
    94→      ) : (
    95→        <div className="surface" style={{ overflow: 'hidden' }}>
    96→          <table className="tbl">
    97→            <thead>
    98→              <tr>
    99→                <th>Frame ID</th>
