   393→}
   394→.kv > div { display: flex; flex-direction: column; gap: 2px; }
   395→.kv .k {
   396→  font-size: 10px; font-weight: 600;
   397→  letter-spacing: 0.06em;
   398→  text-transform: uppercase;
   399→  color: var(--text-secondary);
   400→}
   401→.kv .v { font-size: 14px; color: var(--text-primary); }
   402→.kv .v.muted { color: var(--text-secondary); }
   403→.kv .v.mono { font-family: ui-monospace, Menlo, monospace; font-size: 13px; }
   404→
   405→/* ---------- Section block ---------- */
   406→.section-block { padding: var(--sp-4) var(--sp-3); }
   407→.section-block + .section-block { border-top: 1px solid var(--border-subtle); }
   408→.section-block h2 { font-size: 14px; font-weight: 600; margin-bottom: var(--sp-2); }
   409→.section-block .lead { color: var(--text-secondary); font-size: 12px; margin-top: -6px; margin-bottom: var(--sp-2); }
   410→
   411→/* ---------- Empty state ---------- */
   412→.empty {
   413→  padding: var(--sp-5);
   414→  text-align: center;
   415→  color: var(--text-secondary);
   416→}
   417→
   418→/* ---------- Skeleton "map" ---------- */
   419→.fake-map {
   420→  position: relative;
   421→  background:
   422→    linear-gradient(135deg, #e9eef3 0%, #dde6ee 100%);
   423→  border-radius: var(--radius-lg);
   424→  overflow: hidden;
   425→  border: 1px solid var(--border-subtle);
   426→}
   427→.fake-map::before {
   428→  content: "";
   429→  position: absolute; inset: 0;
   430→  background-image:
   431→    linear-gradient(rgba(255,255,255,0.4) 1px, transparent 1px),
   432→    linear-gradient(90deg, rgba(255,255,255,0.4) 1px, transparent 1px),
   433→    radial-gradient(at 30% 40%, rgba(122,167,87,0.25), transparent 35%),
   434→    radial-gradient(at 70% 60%, rgba(122,167,87,0.22), transparent 30%),
   435→    radial-gradient(at 50% 80%, rgba(4,106,196,0.18), transparent 30%);
   436→  background-size: 32px 32px, 32px 32px, 100% 100%, 100% 100%, 100% 100%;
   437→}
   438→.fake-map::after {
   439→  content: "";
   440→  position: absolute;
   441→  left: 12%; top: 60%;
   442→  width: 70%; height: 3px;
   443→  background: rgba(67,67,67,0.18);
   444→  border-radius: 2px;
   445→  transform: rotate(-8deg);
   446→  box-shadow:
   447→    -120px -180px 0 -1px rgba(67,67,67,0.16),
   448→    180px -90px 0 -1px rgba(67,67,67,0.18),
   449→    -40px 60px 0 -1px rgba(67,67,67,0.14);
   450→}
   451→.fake-map .pins { position: absolute; inset: 0; }
   452→.fake-map .pin {
   453→  position: absolute;
   454→  width: 24px; height: 32px;
   455→  transform: translate(-50%, -100%);
   456→  display: grid; place-items: center;
   457→  color: var(--primary-main);
   458→  filter: drop-shadow(0 2px 3px rgba(0,0,0,0.25));
   459→  cursor: pointer;
   460→}
   461→.fake-map .pin.active { color: var(--error-dark); transform: translate(-50%, -100%) scale(1.25); z-index: 2; }
   462→.fake-map .pin svg { width: 100%; height: 100%; }
   463→.fake-map .legend {
   464→  position: absolute; bottom: 12px; left: 12px;
   465→  background: white;
   466→  border-radius: var(--radius);
   467→  padding: 8px 10px;
   468→  font-size: 11px;
   469→  box-shadow: var(--elev-low);
   470→  display: flex; gap: 12px;
   471→  align-items: center;
   472→}
   473→.fake-map .legend .item { display: flex; align-items: center; gap: 4px; }
   474→.fake-map .legend .dot { width: 8px; height: 8px; border-radius: 50%; }
   475→
   476→/* ---------- Master/detail split (Direction B) ---------- */
   477→.split {
   478→  display: grid;
   479→  grid-template-columns: 380px 1fr;
   480→  height: calc(100vh - 56px);
   481→  background: var(--white);
   482→}
   483→.split .list {
   484→  border-right: 1px solid var(--border-subtle);
   485→  overflow: auto;
   486→  display: flex; flex-direction: column;
   487→}
   488→.split .list .list-head {
   489→  padding: var(--sp-2) var(--sp-2);
   490→  border-bottom: 1px solid var(--border-subtle);
   491→  position: sticky; top: 0; background: var(--white); z-index: 2;
   492→}
   493→.split .list .row {
   494→  padding: 12px 16px;
   495→  border-bottom: 1px solid var(--border-subtle);
   496→  cursor: pointer;
   497→  display: flex; flex-direction: column; gap: 4px;
   498→}
   499→.split .list .row:hover { background: var(--gray-50); }
   500→.split .list .row.active {
   501→  background: var(--blue-50);
   502→  box-shadow: inset 3px 0 0 var(--primary-main);
   503→}
   504→.split .list .row .head {
   505→  display: flex; justify-content: space-between; align-items: center; gap: 6px;
   506→}
   507→.split .list .row .id { font-family: ui-monospace, Menlo, monospace; font-size: 11px; color: var(--text-secondary); font-weight: 500; }
   508→.split .list .row .title { font-weight: 500; font-size: 13px; color: var(--text-primary); }
   509→.split .list .row .sub   { font-size: 12px; color: var(--text-secondary); }
   510→.split .detail { overflow: auto; background: var(--bg-subtle); }
   511→
   512→/* ---------- Filter sidebar (Direction A) ---------- */
   513→.filters {
   514→  width: 264px;
   515→  background: var(--white);
   516→  border-right: 1px solid var(--border-subtle);
   517→  padding: var(--sp-2);
   518→  overflow: auto;
   519→}
   520→.filters h3 {
   521→  font-size: 11px; font-weight: 600;
   522→  text-transform: uppercase; letter-spacing: 0.06em;
   523→  color: var(--text-secondary);
   524→  margin: 10px 4px 8px;
   525→}
   526→.filters .fg + .fg { margin-top: var(--sp-2); }
   527→.filters label.opt {
   528→  display: flex; align-items: center; gap: 8px;
   529→  padding: 5px 4px;
   530→  font-size: 13px;
   531→  color: var(--text-primary);
   532→  cursor: pointer;
   533→  border-radius: 4px;
   534→}
   535→.filters label.opt:hover { background: var(--gray-50); }
   536→.filters label.opt input { accent-color: var(--primary-main); }
   537→.filters label.opt .count { margin-left: auto; color: var(--text-secondary); font-size: 11px; }
   538→.filters .range {
   539→  display: flex; gap: 6px; padding: 4px;
   540→}
   541→.filters .range input {
   542→  height: 30px; font-size: 12px; padding: 0 8px;
   543→  border: 1px solid var(--border-default); border-radius: var(--radius);
   544→  width: 100%; min-width: 0;
   545→}
   546→.filters .clear { font-size: 12px; color: var(--primary-main); cursor: pointer; padding: 4px; }
   547→.filters .clear:hover { text-decoration: underline; }
   548→
   549→/* ---------- Sticky action bar (edit form) ---------- */
   550→.sticky-bar {
   551→  position: sticky; bottom: 0;
   552→  background: var(--white);
   553→  border-top: 1px solid var(--border-subtle);
   554→  padding: 12px var(--sp-3);
   555→  display: flex; gap: 8px; align-items: center;
   556→  box-shadow: 0 -4px 16px -8px rgba(0,34,63,0.18);
   557→}
   558→.sticky-bar .left { color: var(--text-secondary); font-size: 12px; }
   559→.sticky-bar .spacer { flex: 1; }
   560→
   561→/* ---------- Banner ---------- */
   562→.banner {
   563→  background: var(--blue-50);
   564→  border: 1px solid var(--blue-200);
   565→  border-left: 4px solid var(--primary-main);
   566→  padding: 10px 14px;
   567→  border-radius: var(--radius);
   568→  font-size: 13px;
   569→  color: var(--primary-dark);
   570→  display: flex; gap: 10px; align-items: center;
   571→}
   572→.banner svg { flex-shrink: 0; }
   573→
   574→/* ---------- View toggle ---------- */
   575→.view-toggle {
   576→  display: inline-flex;
   577→  border: 1px solid var(--border-default);
   578→  border-radius: var(--radius);
   579→  overflow: hidden;
   580→  height: 36px;
   581→}
   582→.view-toggle button {
   583→  border: none;
   584→  background: var(--white);
   585→  color: var(--text-secondary);
   586→  padding: 0 12px;
   587→  font-size: 12px;
   588→  font-weight: 500;
   589→  cursor: pointer;
   590→  display: inline-flex; align-items: center; gap: 6px;
   591→}
   592→.view-toggle button + button { border-left: 1px solid var(--border-default); }
   593→.view-toggle button.active { background: var(--blue-50); color: var(--primary-main); }
   594→.view-toggle button:hover:not(.active) { background: var(--gray-50); }
   595→
   596→/* ---------- Scrollbar ---------- */
   597→.content::-webkit-scrollbar,
   598→.split ::-webkit-scrollbar,
   599→.filters::-webkit-scrollbar { width: 10px; height: 10px; }
   600→.content::-webkit-scrollbar-thumb,
   601→.split ::-webkit-scrollbar-thumb,
   602→.filters::-webkit-scrollbar-thumb { background: var(--gray-300); border-radius: 6px; border: 2px solid transparent; background-clip: padding-box; }
   603→.content::-webkit-scrollbar-thumb:hover,
   604→.split ::-webkit-scrollbar-thumb:hover,
   605→.filters::-webkit-scrollbar-thumb:hover { background: var(--gray-500); background-clip: padding-box; border: 2px solid transparent; }
   606→
   607→/* ---------- Concept banner above app ---------- */
   608→.concept-bar {
   609→  background: linear-gradient(90deg, var(--gray-1600) 0%, #1a2a3a 100%);
   610→  color: white;
   611→  padding: 8px var(--sp-3);
   612→  display: flex; align-items: center; gap: 16px;
   613→  font-size: 12px;
   614→  border-bottom: 1px solid rgba(255,255,255,0.06);
   615→}
   616→.concept-bar .label { color: rgba(255,255,255,0.6); }
   617→.concept-bar .label b { color: white; font-weight: 600; }
   618→.concept-bar .spacer { flex: 1; }
   619→.concept-bar .key {
   620→  display: inline-block;
   621→  background: rgba(255,255,255,0.1);
   622→  border: 1px solid rgba(255,255,255,0.15);
   623→  padding: 0 6px;
   624→  border-radius: 3px;
   625→  font-family: ui-monospace, Menlo, monospace;
   626→  font-size: 11px;
   627→}
